Here is the original Java 8 code you have to rewrite:
<original_code>
/*
If you want to aim high, aim high
Don't let that studying and grades consume you
Just live life young
******************************
If I'm the sun, you're the moon
Because when I go up, you go down
*******************************
I'm working for the day I will surpass you
https://www.a2oj.com/Ladder16.html
*/
import java.util.*;
import java.io.*;
import java.math.*;

   public class E
   {
      static long MOD = 998244353L;
      public static void main(String omkar[]) throws Exception
      {
         BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));  
         StringTokenizer st = new StringTokenizer(infile.readLine());
         long N = Long.parseLong(st.nextToken());
         long M = Long.parseLong(st.nextToken());
         long L = Long.parseLong(st.nextToken());
         long R = Long.parseLong(st.nextToken());
         //dont panic 
         //that makes you lose Omkar energy
         if((N*M)%2 == 1)
         {
            //here?
            long temp = N*M;
            BigInteger exp = new BigInteger(temp+"");
            BigInteger base = new BigInteger((R-L+1)+"");
            BigInteger mod = new BigInteger(MOD+"");
            long res = base.modPow(exp, mod).longValue();
            System.out.println((res+MOD)%MOD);
         }
         else
         {
            long temp = N*M;
            BigInteger exp = new BigInteger(temp+"");
            BigInteger base = new BigInteger((R-L+1)+"");
            BigInteger mod = new BigInteger(MOD+"");
            long res = base.modPow(exp, mod).longValue();
            //res = (res*power(2,MOD-2,MOD))%MOD;
            if((R-L)%2 == 0)
               res++;
            res = (res*power(2,MOD-2,MOD))%MOD;
            System.out.println(res);
         }
      }
      public static long power(long x, long y, long p) 
      { 
          long res = 1L;      
          x = x % p;  
          while (y > 0) 
          { 
              if((y & 1)==1) 
                  res = (res * x) % p; 
              y = y >> 1;  
              x = (x * x) % p;  
          } 
          return res; 
      }
   }
